def calculate_total_utilization(task_set):
    U_sum = 0.0
    for task_i in task_set:
        U_sum += calculate_task_utilization(task_i.C, task_i.T)
    return U_sum

def is_task_set_schedulable(task_set):
    for task_i in task_set:
        # Assume task_i.R and task_i.D are available
        if not is_task_schedulable(task_i.R, task_i.D):
            return False
    return True

import math

def calculate_dbf(t, D_i, T_i, C_i):
    num_jobs = math.floor((t - D_i) / T_i) + 1
    return max(0, num_jobs * C_i)

def calculate_max_blocking_time(task_k, task_set):
    B_k = 0
    for task_i in task_set:
        # Assuming a priority scheme where lower_priority_value > higher_priority_value
        if task_i.priority > task_k.priority:
            B_k = max(B_k, task_i.C)
    return B_k

def calculate_blocking_factor(B_k, C_k):
    if C_k == 0:
        return float('inf') # Handle division by zero if WCET can be zero
    return B_k / C_k

def categorize_higher_priority_tasks(task_k, hp_tau_k):
    hp1_tau_k = []
    hp2_tau_k = []
    for task_i in hp_tau_k:
        if task_i.T < task_k.D:
            hp1_tau_k.append(task_i)
        else:
            hp2_tau_k.append(task_i)
    return hp1_tau_k, hp2_tau_k

def calculate_C_k_double_prime(B_k, C_k, hp2_tau_k):
    sum_C_hp2 = 0
    for task_i in hp2_tau_k:
        sum_C_hp2 += task_i.C
    return B_k + C_k + sum_C_hp2

import math

def get_tda_test_points(task_k, hp1_tau_k):
    test_points = set()
    for task_i in hp1_tau_k:
        # Last release time of task_i before task_k.D
        t_i_release = math.floor(task_k.D / task_i.T) * task_i.T
        test_points.add(t_i_release)
    test_points.add(task_k.D) # Add the deadline of task_k itself
    return sorted(list(test_points))

def calculate_lp_blocking_time(task_k, task_set):
    B_k_lp = 0
    for task_i in task_set:
        if task_i.priority > task_k.priority: # Assuming lower_priority_value > higher_priority_value
            max_C_i_j_for_task = 0
            # Assuming task_i.non_preemptive_regions is a list of objects with a 'WCET' attribute
            for region_j in task_i.non_preemptive_regions:
                max_C_i_j_for_task = max(max_C_i_j_for_task, region_j.WCET)
            B_k_lp = max(B_k_lp, max_C_i_j_for_task)
    return B_k_lp

import math

def calculate_total_dbf_set(task_set, t):
    total_dbf = 0
    for task_i in task_set:
        total_dbf += calculate_dbf(t, task_i.D, task_i.T, task_i.C)
    return total_dbf

def calculate_blocking_edf_np(task_set, t):
    max_blocking = 0
    for task_i in task_set:
        if task_i.D > t:
            max_blocking = max(max_blocking, task_i.C)
    return max_blocking

def is_edf_np_schedulable(task_set, L_max_busy_interval):
    U_sum = calculate_total_utilization(task_set)
    if U_sum > 1:
        return False

    S_points = set()
    for task_i in task_set:
        k = 1
        while (k * task_i.T + task_i.D) <= L_max_busy_interval:
            S_points.add(k * task_i.T + task_i.D)
            k += 1
    S_points = sorted(list(S_points))

    for t in S_points:
        if t <= 0: continue # Ensure t is positive
        h_t = calculate_total_dbf_set(task_set, t)
        B_t = calculate_blocking_edf_np(task_set, t)
        if (h_t + B_t) / t > 1:
            return False
    return True

