import math

def calculate_rm_np_utilization_bound_theorem4(gamma):
    if gamma <= 1:
        return gamma / (gamma + 1) + math.log(2) / (1 + gamma)
    else: # gamma > 1
        return 1.0 / (1.0 + gamma)

def is_rm_np_schedulable_theorem4(task_set, max_gamma_across_tasks):
