    bound = calculate_rm_np_utilization_bound_theorem4(max_gamma_across_tasks)
    return U_sum <= bound

def check_wcrt_first_job_condition(task_set, is_preemptive_schedulable_func):
    # Condition 1: task set is feasible under preemptive scheduling
    if not is_preemptive_schedulable_func(task_set):
        return False

    # Condition 2: relative deadlines are less than or equal to periods
    for task_i in task_set:
        if task_i.D > task_i.T:
            return False

    return True # If both conditions hold, WCRT occurs in first job

import math

def calculate_interference(t, hp_tau_k):
    interference = 0
    for task_i in hp_tau_k:
        interference += math.floor(t / task_i.T) * task_i.C
    return interference

def is_task_schedulable_lemma3(task_k, hp_tau_k, B_k):
    # Condition 1: First job starts before D_k - C_k
    start_condition_met = False
    # Critical points for start condition (e.g., deadlines of hp tasks within D_k - C_k, and D_k - C_k itself)
    critical_t_start_candidates = set([math.floor((task_k.D - task_k.C) / ti.T) * ti.T for ti in hp_tau_k if ti.T > 0] + [task_k.D - task_k.C])
    critical_t_start = sorted([t for t in critical_t_start_candidates if t > 0 and t <= (task_k.D - task_k.C)])

    for t_val in critical_t_start:
        if B_k + calculate_interference(t_val, hp_tau_k) <= t_val:
            start_condition_met = True
            break
    if not start_condition_met:
        return False

    # Condition 2: Task set is schedulable by A_P (preemptive)
    finish_condition_met = False
    # Critical points for finish condition (e.g., deadlines of hp tasks within D_k, and D_k itself)
    critical_t_finish_candidates = set([math.floor(task_k.D / ti.T) * ti.T for ti in hp_tau_k if ti.T > 0] + [task_k.D])
    critical_t_finish = sorted([t for t in critical_t_finish_candidates if t > 0 and t <= task_k.D])

    for t_val in critical_t_finish:
        if task_k.C + calculate_interference(t_val, hp_tau_k) <= t_val:
            finish_condition_met = True
            break
    if not finish_condition_met:
        return False

    return True

def categorize_hp_tasks_by_deadline(task_k, hp_tau_k, effective_deadline):
    hp1 = []
    hp2 = []
    for task_i in hp_tau_k:
        if task_i.T < effective_deadline:
            hp1.append(task_i)
        else:
            hp2.append(task_i)
    return hp1, hp2

def is_task_schedulable_theorem6(task_k, hp_tau_k, lp_tau_k, task_set):
    B_k = calculate_max_blocking_time(task_k, task_set)

    # Condition 1 (Start Time)
    effective_deadline_NP = task_k.D - task_k.C
    if effective_deadline_NP <= 0: return False # Cannot start if no time left

    hp_NP_1_tau_k, hp_NP_2_tau_k = categorize_hp_tasks_by_deadline(task_k, hp_tau_k, effective_deadline_NP)

    B_k_plus_hp_NP_2_C = B_k
    for task_i in hp_NP_2_tau_k:
        B_k_plus_hp_NP_2_C += task_i.C

    product_NP = 1.0
    for task_j in hp_NP_1_tau_k:
        product_NP *= (calculate_task_utilization(task_j.C, task_j.T) + 1)

    if (B_k_plus_hp_NP_2_C / effective_deadline_NP) + product_NP > 2:
        return False

    # Condition 2 (Finish Time)
    effective_deadline_P = task_k.D
    if effective_deadline_P <= 0: return False # Deadline must be positive

    hp_P_1_tau_k, hp_P_2_tau_k = categorize_hp_tasks_by_deadline(task_k, hp_tau_k, effective_deadline_P)

    C_k_plus_hp_P_2_C = task_k.C
    for task_i in hp_P_2_tau_k:
        C_k_plus_hp_P_2_C += task_i.C

    product_P = 1.0
    for task_j in hp_P_1_tau_k:
        product_P *= (calculate_task_utilization(task_j.C, task_j.T) + 1)

    if (C_k_plus_hp_P_2_C / effective_deadline_P) + product_P > 2:
        return False

    return True

def is_blocking_time_negligible(task_k, hp_tau_k, B_k):
    # Condition 1: T_i <= D_k - C_k for all hp tasks
    for task_i in hp_tau_k:
        if task_i.T > (task_k.D - task_k.C):
            return False

    # Condition 2: B_k <= (1 - C_k / D_k) * C_k
    if task_k.D == 0: # Avoid division by zero
        return False # Or handle as appropriate for D_k=0

    threshold = (1.0 - (task_k.C / task_k.D)) * task_k.C
    if B_k > threshold:
        return False

    return True

formal_description.statement:
Suppose that the tasks are indexed such that T_i <= T_i_plus_1. If gamma = B_k / C_k, then task tau_k is schedulable by RM-NP if sum_{i=1 to k} U_i <= min{k * (2_power_1_over_k - 1), H_k_gamma}
where H_k_gamma = {
    (k - 1) * (2_power_1_over_k_minus_1 - 1)                                                                                               if gamma <= (1/2)_power_1_over_k_minus_1;
    (2/gamma)_power_1_over_k * gamma / (1 + (2/gamma)_power_1_over_k * gamma) + (k - 1) * ((2/gamma)_power_1_over_k)  if (1/2)_power_1_over_k_minus_1 < gamma <= 2;
    1 / (1 + gamma)                                                                                                 if gamma > 2
}

informal_sketch.pseudocode:
import math

def calculate_H_k_gamma(k, gamma):
    if k <= 1: 
        return 1.0 / (1.0 + gamma) if gamma > 0 else 1.0

    term_half_power_k_minus_1 = (0.5)**(1.0/(k-1))

    if gamma <= term_half_power_k_minus_1:
        return (k-1) * ((2**(1.0/(k-1))) - 1)
    elif term_half_power_k_minus_1 < gamma <= 2:
        term_2_over_gamma_power_k = (2.0 / gamma)**(1.0/k)
        numerator = term_2_over_gamma_power_k * gamma
        denominator = 1.0 + term_2_over_gamma_power_k * gamma
        return numerator / denominator + (k-1) * term_2_over_gamma_power_k
    else: # gamma > 2
        return 1.0 / (1.0 + gamma)

def calculate_rm_np_utilization_bound_theorem8(k, gamma):
    # Liu & Layland bound for RM-P
    rm_p_bound = k * ((2**(1.0/k)) - 1)

    h_k_gamma_bound = calculate_H_k_gamma(k, gamma)

    return min(rm_p_bound, h_k_gamma_bound)

def is_rm_np_schedulable_theorem8(task_set, gamma_val_for_k):
    k = len(task_set)
    U_sum = calculate_total_utilization(task_set)
    bound = calculate_rm_np_utilization_bound_theorem8(k, gamma_val_for_k)
    return U_sum <= bound

