import math

def calculate_rm_np_utilization_bound_theorem9(gamma):
    if gamma <= 1:
        return math.log(2) # approx 0.693
    elif 1 < gamma <= 2:
        return (gamma - 1.0) / (2.0 * gamma - 1.0) + math.log(2.0 / gamma)
    else: # gamma > 2
        return 1.0 / (1.0 + gamma)

def is_rm_np_schedulable_theorem9(task_set, max_gamma_across_tasks):
    U_sum = calculate_total_utilization(task_set)
    bound = calculate_rm_np_utilization_bound_theorem9(max_gamma_across_tasks)
    return U_sum <= bound
